/**
 * Redux Action Types
 * Defines the types of actions that can be dispatched in the application
 */

// Action type for fetching todos from the API
export const FETCH_TODOS = "FETCH_TODOS";

// Action type for adding a new todo
export const ADD_TODO = "ADD_TODO";
